from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.fast_previous = None
        self.slow_previous = None

        self._bucket_start = None
        self._bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_date = None
        self._blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._HandleUnexpectedSpyPosition()
        self._ProcessMinuteExitLogic(slice)

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        completed_bar = self._AddMinuteToFiveMinuteBar(bar)
        if completed_bar is None:
            return

        self._UpdateMovingAverages(completed_bar)

        if not self._AveragesReady():
            return

        end_time = completed_bar.EndTime
        if not (time(9, 45) <= end_time.time() <= time(14, 30)):
            return

        if self._blocked_entry_date == self.Time.date():
            return

        if self.held_option is not None or self._EntryOrderIsOpen():
            return

        bullish = (
            self.fast_previous is not None
            and self.slow_previous is not None
            and self.fast_previous <= self.slow_previous
            and self.fast_values[-1] > self.slow_values[-1]
        )

        if bullish:
            self._TryEnter(slice)

    def _AddMinuteToFiveMinuteBar(self, minute_bar):
        end = minute_bar.EndTime
        local_end = end.astimezone(self.TimeZone)
        minute = local_end.replace(second=0, microsecond=0)

        anchor = minute.replace(hour=9, minute=30)
        if minute < anchor:
            return None

        elapsed = int((minute - anchor).total_seconds() // 60)
        bucket_index = elapsed // 5
        bucket_start = anchor + timedelta(minutes=bucket_index * 5)

        if self._bucket_start is None:
            self._bucket_start = bucket_start

        if bucket_start != self._bucket_start:
            completed = self._FinalizeFiveMinuteBar()
            self._bucket_start = bucket_start
            self._bucket_bars = [minute_bar]
            return completed

        self._bucket_bars.append(minute_bar)

        if len(self._bucket_bars) == 5:
            expected = [
                self._bucket_start + timedelta(minutes=i)
                for i in range(1, 6)
            ]
            actual = [
                b.EndTime.astimezone(self.TimeZone).replace(
                    second=0, microsecond=0
                )
                for b in self._bucket_bars
            ]
            if actual == expected:
                return self._FinalizeFiveMinuteBar()

        return None

    def _FinalizeFiveMinuteBar(self):
        bars = self._bucket_bars
        self._bucket_bars = []

        if len(bars) != 5:
            return None

        local_times = [
            b.EndTime.astimezone(self.TimeZone).replace(
                second=0, microsecond=0
            )
            for b in bars
        ]
        expected = [
            self._bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]
        if local_times != expected:
            return None

        first = bars[0]
        last = bars[-1]
        return TradeBar(
            self._bucket_start,
            self.spy,
            first.Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            last.Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

    def _UpdateMovingAverages(self, bar):
        if len(self.slow_values) >= 20:
            self.fast_previous = sum(list(self.slow_values)[-5:]) / 5.0
            self.slow_previous = sum(self.slow_values) / 20.0

        self.fast_values.append(bar.Close)
        self.slow_values.append(bar.Close)

    def _AveragesReady(self):
        return len(self.fast_values) >= 5 and len(self.slow_values) >= 20

    def _TryEnter(self, slice: Slice):
        if self._blocked_entry_date == self.Time.date():
            return

        chains = slice.OptionChains
        chain = chains.get(self.option_canonical)
        if chain is None:
            self.Debug("Skipped entry: no current SPY option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            c.Expiry.date() for c in chain
            if c.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days out.")
            return

        expiry = expirations[0]
        minimum_strike = 1.01 * self.Securities[self.spy].Price

        candidates = [
            c for c in chain
            if c.Expiry.date() == expiry
            and c.Right == OptionRight.Call
            and c.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        contract = candidates[0]

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                contract.Symbol, expiry, contract.Strike
            )
        )

    def _ProcessMinuteExitLogic(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        security = self.Securities[self.held_option]
        if not security.Invested:
            return

        if self._IsTimeStopDue():
            self._SubmitExit("expiration-eve time stop")
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._SubmitExit("50% profit target")

    def _IsTimeStopDue(self):
        if self.expiration_date is None:
            return False

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        next_trading_day = exchange_hours.GetNextTradingDay(self.Time.date())

        return (
            next_trading_day == self.expiration_date
            and self.Time.time() >= time(15, 45)
        )

    def _SubmitExit(self, reason):
        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        if self.entry_ticket is not None:
            self.Transactions.CancelOpenOrders(self.held_option)

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option, -quantity, tag=reason
            )
            self.Debug("Exit submitted: {0}".format(reason))

    def _EntryOrderIsOpen(self):
        return (
            self.entry_ticket is not None
            and not self.entry_ticket.Status.IsClosed()
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = order_event.Symbol.ID.Date.date()
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_option, self.entry_price
                    )
                )
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled
            ] and not self.Portfolio[order_event.Symbol].Invested:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.held_option = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option exercise or assignment handled.")
        self._blocked_entry_date = self.Time.date()
        if self.Portfolio[self.spy].Quantity != 0:
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="liquidate unexpected assignment"
            )

    def _HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY equity position liquidated.")
            self._blocked_entry_date = self.Time.date()
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="liquidate unexpected SPY position"
            )

    def OnEndOfDay(self):
        if self.held_option is not None and self.expiration_date is not None:
            if self.Time.date() >= self.expiration_date:
                self._blocked_entry_date = self.Time.date()
                self._SubmitExit("expiration processing liquidation")

