from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy.SetExtendedMarketHours(False)

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiry_date = None
        self.assignment_handled_today = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        if bar.Symbol != self.spy.Symbol:
            return

        local_end = bar.EndTime.astimezone(self.TimeZone)
        if local_end.time() < time(9, 35) or local_end.time() > time(16, 0):
            return

        # Do not bridge missing minute data with a synthetic five-minute bar.
        if bar.EndTime - bar.Time != timedelta(minutes=5):
            return

        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        if not (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            return

        if not (time(9, 45) <= local_end.time() <= time(14, 30)):
            return

        if self.held_symbol is not None or self._entry_is_open():
            return

        self.TryEnter(slice_=None)

    def OnData(self, slice):
        # Exercise or assignment must never leave an SPY equity position open.
        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            if self.assignment_handled_today != self.Time.date():
                self.Debug(
                    f"Unexpected exercise/assignment handling: liquidating "
                    f"{self.Portfolio[self.spy.Symbol].Quantity} SPY shares."
                )
                self.assignment_handled_today = self.Time.date()
                self.Liquidate(self.spy.Symbol, "Unexpected exercise or assignment")

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            self.ManageOpenPosition(slice)

        # The crossover callback runs before OnData for the same consolidated bar.
        # Entry selection therefore uses the current Slice when called here.
        if getattr(self, "_pending_entry_signal", False):
            self._pending_entry_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice_):
        if slice_ is None:
            self._pending_entry_signal = True
            return

        if self.held_symbol is not None or self._entry_is_open():
            return

        chains = list(slice_.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        today = self.Time.date()
        eligible = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                expiry_date = contract.Expiry.date()
                if expiry_date >= today + timedelta(days=7):
                    eligible.append(contract)

        if not eligible:
            self.Debug("Skipped entry: no expiration satisfies the seven-day rule.")
            return

        nearest_expiry = min(c.Expiry.date() for c in eligible)
        price = self.Securities[self.spy.Symbol].Price
        minimum_strike = price * 1.01

        candidates = [
            c for c in eligible
            if c.Expiry.date() == nearest_expiry
            and c.Right == OptionRight.Call
            and c.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no call meets the strike rule.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        self.AddSecurity(selected.Symbol, Resolution.Minute)

        self.entry_ticket = self.MarketOrder(
            selected.Symbol, 1, tag="Bullish crossover entry"
        )
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def ManageOpenPosition(self, slice):
        local_now = self.Time.astimezone(self.TimeZone)

        if self.expiry_date is not None:
            if local_now.date() >= self.expiry_date:
                self.SubmitExit("Expiration protection")
                return

            if (
                local_now.date() == self.expiry_date - timedelta(days=1)
                and local_now.time() >= time(15, 45)
            ):
                self.SubmitExit("Expiration time stop")
                return

        if self.entry_price is None or self.exit_ticket is not None:
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        if self.entry_ticket is not None and self._entry_is_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
